const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
export function createGlobal(ctx){
 let shelters=null,clans=null,stories=null,loading=new Set(),error='',locale=(navigator.language||'it').slice(0,2),units=/^en-US/i.test(navigator.language)?'us':'metric';
 try{locale=localStorage.getItem('ms-locale')||locale;units=localStorage.getItem('ms-units')||units}catch{}if(!['it','en','de','fr','es'].includes(locale))locale='en';
 const labels={it:{stories:'Meteo-Stories',shelters:'Luoghi coperti',risk:'Rischio storico grandine',unknown:'Dati non disponibili',clans:'Meteo-Clans',original:'Mostra originale',translate:'Traduci',language:'Lingua dei contenuti'},en:{stories:'Weather Stories',shelters:'Covered places',risk:'Historical hail risk',unknown:'Data unavailable',clans:'Weather Clans',original:'Show original',translate:'Translate',language:'Content language'},de:{stories:'Wetter-Stories',shelters:'Überdachte Orte',risk:'Historisches Hagelrisiko',unknown:'Keine Daten verfügbar',clans:'Wetter-Clans',original:'Original anzeigen',translate:'Übersetzen',language:'Sprache der Inhalte'}};
 const t=k=>(labels[locale]||labels.en)[k];
 function settings(){return `<div class="global-settings"><label>${t('language')}<select id="content-locale">${[['it','Italiano'],['en','English'],['de','Deutsch'],['fr','Français'],['es','Español']].map(([v,n])=>`<option value="${v}" ${locale===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Unità del riepilogo<select id="content-units"><option value="metric" ${units==='metric'?'selected':''}>°C · km/h</option><option value="us" ${units==='us'?'selected':''}>°F · mph</option></select></label></div>`}
 function overview(){const w=ctx.get().weather,c=w?.current,temp=c?(units==='us'?Math.round(c.temperature_2m*9/5+32)+' °F':Math.round(c.temperature_2m)+' °C'):'—',wind=c?(units==='us'?(c.wind_speed_10m*.621371).toFixed(1)+' mph':c.wind_speed_10m+' km/h'):'—';return `<section class="global-overview"><div class="row"><h2>Il quadro della tua zona</h2><span class="tag">Fonte: Open-Meteo</span></div>${settings()}<div class="global-grid"><article class="card"><span class="eyebrow">METEO LOCALE</span><h2>${temp}</h2><p>Vento ${wind}</p><p class="small">${w?esc(w.current.time.replace('T',' ')):'In attesa della fonte'}</p><a href="#tendenze">Previsioni complete →</a></article><article class="card risk-unknown"><span class="eyebrow">${t('risk')}</span><h2>— / 100</h2><p>${t('unknown')}</p><p class="small">Serve un archivio storico calibrato. Nessun punteggio non significa rischio basso.</p><a href="#radar">Fonti e copertura →</a></article></div><div class="feature-links"><a href="#stories">▥ ${t('stories')}</a><a href="#ripari">⌂ ${t('shelters')}</a><a href="#clan">◎ ${t('clans')}</a><a href="#radar">◉ Radar e allerte</a></div></section>`}
 function radar(){const country=ctx.get().place.country_code;const region=country==='US'?'us':country==='IT'?'it':'eu';return `<span class="eyebrow">FONTI, NON SUPPOSIZIONI</span><h1>Radar e allerte</h1><p>Le fonti radar e i bollettini ufficiali sono servizi diversi. Qui trovi i collegamenti ai fornitori.</p><section class="card"><label class="field"><span>Area della fonte</span><select id="radar-region"><option value="it" ${region==='it'?'selected':''}>Italia · Radar-DPC</option><option value="eu" ${region==='eu'?'selected':''}>Europa · MeteoAlarm (allerte)</option><option value="us" ${region==='us'?'selected':''}>Stati Uniti · NWS</option></select></label><div id="radar-provider"></div></section><section class="card risk-unknown"><h2>Traiettoria grandine: non disponibile</h2><p>Non è collegato un servizio di tracciamento delle celle. Nessun conto alla rovescia, poligono di rischio o messaggio “grandine fra 12 minuti” viene generato.</p><p>Il globo 3D è geografico. Non rappresenta un radar meteorologico.</p></section>`}
 function provider(){const v=$('#radar-region').value,items={it:['Radar-DPC','https://radar.protezionecivile.it/','Radar nazionale italiano · contenuto esterno'],eu:['MeteoAlarm','https://www.meteoalarm.org/','Allerte europee · non un radar delle precipitazioni'],us:['NWS Radar','https://radar.weather.gov/','Radar statunitense · contenuto esterno']},[name,url,desc]=items[v];$('#radar-provider').innerHTML=`<h2>${name}</h2><p>${desc}</p><a class="button" href="${url}" target="_blank" rel="noopener">Apri la fonte ufficiale ↗</a><p class="small">Il livello radar non è ancora importato nell’app. Controlla sempre data, copertura e legenda del fornitore.</p>`}
 function shelterPage(){return `<span class="eyebrow">COMMUNITY SUL TERRITORIO</span><h1>${t('shelters')}</h1><p>Parcheggi e luoghi coperti segnalati dalle persone. Accesso, sicurezza e posti liberi non sono verificati.</p><a href="#offline" class="button">Salva per quando sei offline</a><button id="add-shelter" class="button">Segnala un luogo pubblico</button><p class="small">Non aggiungere abitazioni private. Nessun luogo è indicato come disponibile in tempo reale.</p>${error?`<p role="alert">${esc(error)}</p>`:''}<div class="shelter-list">${shelters?.length?shelters.map(p=>`<article class="card"><span class="tag">Community · non verificato</span><h2>${esc(p.name)}</h2><p>${esc(p.city)}</p><p>${esc(p.details)}</p><p class="small">Posti liberi: sconosciuti · segnalato il ${new Date(p.created).toLocaleDateString()}</p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.lat+','+p.lon)}" target="_blank" rel="noopener" class="button">Vedi il punto sulla mappa ↗</a><div class="actions"><button data-shelter-report="${p.id}">Segnala un problema</button>${p.author===ctx.get().me?.id?`<button data-shelter-delete="${p.id}">Elimina</button>`:''}</div></article>`).join(''):`<section class="card"><h2>${shelters?'Nessun luogo ancora condiviso.':'Caricamento…'}</h2><p>Non mostriamo parcheggi o disponibilità inventati.</p></section>`}</div>`}
 function clanPage(){return `<span class="eyebrow">LA TUA ZONA, LA TUA SQUADRA</span><h1>${t('clans')}</h1><p>Entra nel gruppo della tua città. La classifica qui conta i membri, non certifica la qualità delle segnalazioni.</p><section class="card"><h2>${esc(clans?.mine||'Scegli la tua squadra')}</h2><p>Storm Coins: <b>0</b> · Reputazione: non ancora valutata.</p><p class="small">I premi per eventi verificati non sono attivi finché manca un processo di verifica operativo.</p><button id="join-clan" class="button">Scegli città / quartiere</button>${clans?.mine?'<button id="leave-clan">Lascia il gruppo</button>':''}</section>${error?`<p role="alert">${esc(error)}</p>`:''}<section class="card"><h2>Gruppi della community</h2>${clans?.clans.map(c=>`<div class="week-row"><b>${esc(c.clan)}</b><span>${c.members} membri</span></div>`).join('')||'<p>Le prime squadre iniziano qui.</p>'}</section>`}
 function storyReactions(p){return '<div class="reaction-group" aria-label="Reazioni meteo">'+[['heat','🔥','Caldo'],['snow','❄️','Neve'],['storm','⚡','Temporale']].map(([kind,icon,label])=>'<button data-story-reaction="'+kind+'" data-target="'+p.id+'" aria-label="'+label+'" aria-pressed="'+Boolean(stories?.links?.some(l=>l.kind===kind&&l.target===p.id))+'">'+icon+' '+(p[kind+'_count']||0)+'</button>').join('')+'</div>'}
 function storiesPage(){return `<span class="eyebrow">DA OGNI CIELO</span><h1>${t('stories')}</h1><p>Foto, osservazioni e piccoli momenti della community.</p>${settings()}<a href="#community" class="button">Condividi un momento</a><p class="small">Traduzioni IA disponibili quando OpenAI è collegato. L’originale resta sempre visibile.</p>${error?`<p role="alert">${esc(error)}</p>`:''}<div class="stories-feed">${stories?.posts?.map(p=>`<article class="story-item" id="story-${p.id}">${p.photo?`<img src="/api/photo/${p.id}" loading="lazy" alt="${esc(p.text.slice(0,160))}">`:'<div class="story-sky" aria-hidden="true">☁</div>'}<div class="story-caption"><span class="tag">${esc(p.kind)} · non verificato</span><h2>${esc(p.name)} · ${esc(p.city)}</h2><p>${esc(p.text)}</p><p class="story-translation" id="translation-${p.id}" role="status"></p>${storyReactions(p)}<div class="actions"><button data-translate="${p.id}">${t('translate')}</button>${p.photo&&p.author===ctx.get().me?.id?`<button data-analyze="${p.id}">Analizza la mia foto</button>`:''}<a class="button" href="#community">Commenta / reagisci</a></div></div></article>`).join('')||'<section class="card"><h2>Il feed aspetta il tuo cielo.</h2><p>Nessun contenuto social esterno è stato importato.</p></section>'}</div>${stories?.more?'<button id="more-stories" class="wide">Carica altri momenti</button>':''}<section class="card"><h2>Trending on Socials</h2><p>Importazione non attiva. Servono collegamenti autorizzati alle piattaforme e diritti di utilizzo: non ripubblichiamo automaticamente video altrui.</p></section>`}
 async function load(type,more=false){if(loading.has(type))return;loading.add(type);error='';try{if(type==='stories'){const before=more?Math.min(...stories.posts.map(p=>p.created)):null;const d=await ctx.api('posts'+(before?'?before='+before:''));const blocked=new Set(d.links.filter(l=>l.kind==='block').map(l=>l.target));d.posts=d.posts.filter(p=>!blocked.has(p.author));stories=more?{...d,posts:[...stories.posts,...d.posts]}:d}else if(type==='ripari')shelters=(await ctx.api('global/shelters')).shelters;else clans=await ctx.api('global/clans')}catch(err){error=err.message}finally{loading.delete(type);if(ctx.get().route===type)ctx.render()}}
 function bind(){const r=ctx.get().route;document.querySelectorAll('[data-story-reaction]').forEach(b=>b.onclick=async()=>{if(!ctx.get().me)return ctx.login();b.disabled=true;try{const active=b.getAttribute('aria-pressed')!=='true',kind=b.dataset.storyReaction,id=b.dataset.target;await ctx.api('link',{kind,target:id,active});const p=stories.posts.find(p=>p.id===id);p[kind+'_count']=Math.max(0,(p[kind+'_count']||0)+(active?1:-1));stories.links=stories.links.filter(l=>!(l.kind===kind&&l.target===id));if(active)stories.links.push({kind,target:id});b.setAttribute('aria-pressed',String(active));b.textContent=({heat:'🔥',snow:'❄️',storm:'⚡'})[kind]+' '+p[kind+'_count']}catch(e){ctx.toast(e.message)}finally{b.disabled=false}});$('#content-locale')?.addEventListener('change',ev=>{locale=ev.target.value;try{localStorage.setItem('ms-locale',locale)}catch{}ctx.render()});$('#content-units')?.addEventListener('change',ev=>{units=ev.target.value;try{localStorage.setItem('ms-units',units)}catch{}ctx.render()});if($('#radar-region')){$('#radar-region').onchange=provider;provider()}
 if(r==='ripari'&&shelters===null&&!error)load(r);if(r==='clan'&&clans===null&&!error)load(r);if(r==='stories'&&stories===null&&!error)load(r);$('#more-stories')?.addEventListener('click',()=>load('stories',true));
 $('#add-shelter')?.addEventListener('click',()=>{if(!ctx.get().me)return ctx.login();ctx.modal('Segnala un luogo coperto',`<label class="field"><span>Nome del luogo</span><input id="s-name" required maxlength="100"></label><label class="field"><span>Città</span><input id="s-city" required maxlength="80" value="${esc(ctx.get().place.name)}"></label><p>Inserisci il punto del luogo pubblico, non la tua posizione personale.</p><div class="compose-fields"><label>Latitudine<input id="s-lat" type="number" step="any" min="-90" max="90" required></label><label>Longitudine<input id="s-lon" type="number" step="any" min="-180" max="180" required></label></div><label class="field"><span>Accesso, orari, eventuali limitazioni</span><textarea id="s-details" required maxlength="500"></textarea></label><label><input id="s-public" type="checkbox" required style="width:auto;min-height:0"> Confermo che è un luogo pubblico, non un’abitazione privata.</label>`,async()=>{await ctx.api('global/shelter',{name:$('#s-name').value,city:$('#s-city').value,latitude:Number($('#s-lat').value),longitude:Number($('#s-lon').value),details:$('#s-details').value,publicPlace:$('#s-public').checked});await load('ripari')})});
 document.querySelectorAll('[data-shelter-delete]').forEach(b=>b.onclick=()=>ctx.modal('Elimina il luogo','<p>Rimuovi la tua segnalazione dalla lista pubblica.</p>',async()=>{await ctx.api('global/delete-shelter',{id:b.dataset.shelterDelete});await load('ripari')}));document.querySelectorAll('[data-shelter-report]').forEach(b=>b.onclick=()=>{if(!ctx.get().me)return ctx.login();ctx.modal('Segnala un problema','<label class="field"><span>Motivo</span><input id="s-reason" required maxlength="200"></label>',async()=>{await ctx.api('global/report-shelter',{id:b.dataset.shelterReport,reason:$('#s-reason').value});ctx.toast('Segnalazione ricevuta. Revisione non immediata.')})});
 $('#join-clan')?.addEventListener('click',()=>{if(!ctx.get().me)return ctx.login();ctx.modal('La tua squadra',`<label class="field"><span>Città o quartiere</span><input id="clan-name" required maxlength="80" value="${esc(ctx.get().place.name)}"></label>`,async()=>{await ctx.api('global/clan',{clan:$('#clan-name').value});await load('clan')})});$('#leave-clan')?.addEventListener('click',()=>ctx.modal('Lascia la squadra','<p>Puoi entrare in un altro gruppo in seguito.</p>',async()=>{await ctx.api('global/leave-clan',{});await load('clan')}));
 document.querySelectorAll('[data-translate]').forEach(b=>b.onclick=async()=>{if(!ctx.get().me)return ctx.login();const target=$('#translation-'+b.dataset.translate);b.disabled=true;target.textContent='Traduzione…';try{const d=await ctx.api('global/translate',{id:b.dataset.translate,locale});target.textContent='Traduzione automatica ('+locale+'): '+d.text}catch(err){target.textContent=err.message}finally{b.disabled=false}});
 document.querySelectorAll('[data-analyze]').forEach(b=>b.onclick=()=>ctx.modal('Analisi della tua foto','<p>La foto e la descrizione saranno inviate a OpenAI per una valutazione. Non certifica autenticità, luogo o dimensione della grandine.</p>',async()=>{const d=await ctx.api('global/analyze',{id:b.dataset.analyze});$('#translation-'+b.dataset.analyze).textContent='Valutazione IA non verificata: '+d.summary+' · '+d.uncertainties.join(' ');return true}));
 }
 return {overview,radar,shelterPage,clanPage,storiesPage,bind};
}
